// 1. รับข้อมูล
const rows = $input.all();

let totalMonthlyIncome = 0;  // รายรับทั้งเดือน
let totalMonthlyExpense = 0; // [เพิ่ม] รายจ่ายทั้งเดือน
let totalWeeklyExpense = 0;  // รายจ่าย 7 วัน
let countWeekly = 0;         // นับจำนวนรายการ 7 วัน
let catMap = {};             // หมวดหมู่รายจ่าย 7 วัน

// 2. กำหนดเวลาปัจจุบัน
const today = new Date();
today.setHours(23, 59, 59, 999);

// 2.1 กำหนดช่วงเวลา "สัปดาห์นี้" (7 วันย้อนหลัง)
const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(today.getDate() - 7);
sevenDaysAgo.setHours(0, 0, 0, 0);

// 2.2 กำหนดช่วงเวลา "เดือนนี้" (วันที่ 1 ของเดือนปัจจุบัน)
const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
startOfMonth.setHours(0, 0, 0, 0);

// 3. วนลูปเช็คข้อมูล
for (const item of rows) {
  const row = item.json;
  if (row.date) {
    const rowDate = new Date(row.date);
    const amount = parseFloat(row.amount) || 0;

    // เช็คประเภท (Income/Expense)
    const typeRaw = row['transaction_type (income/expense/transfer)'] || row['type'] || row['transaction_type'] || "";
    const type = typeRaw.toString().toLowerCase();
    const category = row['category'] || 'อื่นๆ';

    // --- Logic 1: ข้อมูลระดับ "เดือนนี้" (รายรับ + รายจ่าย) ---
    if (rowDate >= startOfMonth && rowDate <= today) {
      // 1.1 คิดรายรับ
      if (type.includes('income') || type.includes('รายรับ')) {
        totalMonthlyIncome += amount;
      }
      // 1.2 [เพิ่ม] คิดรายจ่ายทั้งเดือน
      if (type.includes('expense') || type.includes('รายจ่าย')) {
        totalMonthlyExpense += amount;
      }
    }

    // --- Logic 2: ข้อมูลระดับ "สัปดาห์นี้" (7 วันย้อนหลัง) ---
    if (rowDate >= sevenDaysAgo && rowDate <= today) {
      if (type.includes('expense') || type.includes('รายจ่าย')) {
        totalWeeklyExpense += amount;

        // เก็บยอดหมวดหมู่ (เฉพาะรายจ่าย week นี้)
        if (catMap[category]) {
          catMap[category] += amount;
        } else {
          catMap[category] = amount;
        }
        countWeekly++;
      }
    }
  }
}

// 4. จัดอันดับหมวดหมู่ (Top 5 ของ Week นี้)
const sortedCats = Object.entries(catMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

// สร้างข้อความสรุป Top 5 (ใช้ \\n แทน \n เพื่อไม่ให้ JSON พัง)
let topCatText = "";
if (sortedCats.length > 0) {
    topCatText = sortedCats.map((item, index) => {
        const safeName = item[0].replace(/"/g, '\\"');
        return `${index + 1}. ${safeName}: -${item[1].toLocaleString()} ฿`;
    }).join("\\n");
} else {
    topCatText = "- ไม่มีรายจ่ายสัปดาห์นี้ -";
}

// [แก้] คำนวณคงเหลือจริง (รายรับทั้งเดือน - รายจ่ายทั้งเดือน)
const netBalance = totalMonthlyIncome - totalMonthlyExpense;

// 5. ส่งผลลัพธ์
return {
  week_range: sevenDaysAgo.toLocaleDateString('th-TH') + ' - ' + today.toLocaleDateString('th-TH'),
  month_name: startOfMonth.toLocaleDateString('th-TH', { month: 'long', year: 'numeric' }),

  total_income: totalMonthlyIncome,
  total_expense: totalWeeklyExpense,
  net_balance: netBalance,
  tx_count: countWeekly,

  weekly_income_formatted: "0", 
  weekly_expense_formatted: totalWeeklyExpense.toLocaleString(),

  monthly_income_formatted: totalMonthlyIncome.toLocaleString(),
  monthly_expense_formatted: totalMonthlyExpense.toLocaleString(), // [แก้] ใช้ตัวเลขรายจ่ายทั้งเดือนจริงๆ แล้ว

  balance_formatted: netBalance.toLocaleString(),
  top_categories_text: topCatText
};

