// รับข้อมูล
const rows = $input.all();

let todayIncome = 0;
let todayExpense = 0;
let todayCount = 0;
let catMap = {};

// กำหนดเวลาวันนี้
const today = new Date();
today.setHours(0, 0, 0, 0);
const endOfDay = new Date();
endOfDay.setHours(23, 59, 59, 999);

// วนลูปเช็คข้อมูล
for (const item of rows) {
  const row = item.json;
  if (row.date) {
    const rowDate = new Date(row.date);
    const amount = parseFloat(row.amount) || 0;

    const typeRaw = row['transaction_type (income/expense/transfer)'] || row['type'] || row['transaction_type'] || "";
    const type = typeRaw.toString().toLowerCase();
    const category = row['category'] || 'อื่นๆ';

    // เฉพาะรายการวันนี้
    if (rowDate >= today && rowDate <= endOfDay) {
      todayCount++;

      if (type.includes('income') || type.includes('รายรับ')) {
        todayIncome += amount;
      }
      if (type.includes('expense') || type.includes('รายจ่าย')) {
        todayExpense += amount;

        if (catMap[category]) {
          catMap[category] += amount;
        } else {
          catMap[category] = amount;
        }
      }
    }
  }
}

// จัดอันดับหมวดหมู่
const sortedCats = Object.entries(catMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3);

let topCatText = '';
if (sortedCats.length > 0) {
  sortedCats.forEach((item, index) => {
    topCatText += `${index + 1}. ${item[0]}: ฿${item[1].toLocaleString('th-TH')}\n`;
  });
} else {
  topCatText = '- ยังไม่มีรายการวันนี้ -';
}

const balance = todayIncome - todayExpense;

const formatNum = (num) => {
  return num.toLocaleString('th-TH', {minimumFractionDigits: 0, maximumFractionDigits: 2});
};

const formatDate = (date) => {
  return date.toLocaleDateString('th-TH', { day: '2-digit', month: 'long', year: 'numeric' });
};

// ⭐ สำคัญ: คืนค่าแบบอาร์เรย์พร้อม pairedItem
return [
  {
    json: {
      date: formatDate(today),
      income: todayIncome,
      expense: todayExpense,
      balance: balance,
      count: todayCount,
      top_categories: topCatText.trim(),
      income_formatted: formatNum(todayIncome),
      expense_formatted: formatNum(todayExpense),
      balance_formatted: formatNum(balance)
    },
    pairedItem: 0
  }
];

