    const amount = parseFloat(row.amount) || 0;

    // ตรวจสอบประเภทรายการ
    const typeRaw = row['transaction_type (income/expense/transfer)'] || row['type'] || "";
    const type = typeRaw.toString().toLowerCase();
    const category = row['category'] || 'อื่นๆ';

    // เงื่อนไข: ต้องเป็นรายการใน 7 วันล่าสุด
    if (rowDate >= sevenDaysAgo && rowDate <= today) {
      count++;

      if (type.includes('income') || type.includes('รายรับ')) {
        weeklyIncome += amount;
      }
      else if (type.includes('expense') || type.includes('รายจ่าย')) {
        weeklyExpense += amount;
        // เก็บสถิติหมวดหมู่
        if (catMap[category]) {
          catMap[category] += amount;
        } else {
          catMap[category] = amount;
        }
      }
    }
  }
}

// จัดอันดับ Top 3 หมวดหมู่
const sortedCats = Object.entries(catMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3);

let topCatText = '';
if (sortedCats.length > 0) {
  sortedCats.forEach((item, index) => {
    topCatText += `${index + 1}. ${item[0]}: ฿${item[1].toLocaleString('th-TH')}\n`;
  });
} else {
  topCatText = '- ไม่มีรายการ -';
}

// คำนวณคงเหลือ
const balance = weeklyIncome - weeklyExpense;

// ฟอร์แมตตัวเลขและวันที่
const formatNum = (num) => num.toLocaleString('th-TH', {minimumFractionDigits: 0, maximumFractionDigits: 2});
const formatDate = (d) => d.toLocaleDateString('th-TH', { day: '2-digit', month: 'short' });
const weekRange = `${formatDate(sevenDaysAgo)} - ${formatDate(today)}`;

// ส่งค่าออกไป
return {
  week_range: weekRange,
  weekly_income_formatted: formatNum(weeklyIncome),
  weekly_expense_formatted: formatNum(weeklyExpense),
  balance_formatted: formatNum(balance),
  top_categories: topCatText.trim(),
  count: count,
  month_name: "7 วันล่าสุด" // ใช้แทนชื่อเดือนใน Template เดิม
};

