// รับข้อความที่ผู้ใช้พิมพ์มา
const text = $input.item.json.body.events[0].message.text || "";

// แยกข้อความด้วย "ช่องว่าง" (Space)
// ตัวอย่าง: "ข้าวผัด 50" -> ["ข้าวผัด", "50"]
const parts = text.trim().split(" ");

// ดึงตัวสุดท้ายมาเป็น "ราคา"
const amountRaw = parts.pop(); 
const amount = parseFloat(amountRaw);

// เอาส่วนที่เหลือมารวมกันเป็น "ชื่อรายการ"
const item = parts.join(" ");

// เช็คว่าเป็นตัวเลขจริงไหม? (ถ้าไม่ใช่ แสดงว่าพิมพ์ผิด)
const isValid = !isNaN(amount) && amount > 0 && item.length > 0;

// เตรียมวันที่ปัจจุบัน
const now = new Date();
const dateStr = now.toISOString().split('T')[0]; // YYYY-MM-DD
const timeStr = now.toTimeString().split(' ')[0].substring(0, 5); // HH:MM

return {
  isValid: isValid,
  item: item,      // ชื่อรายการ (เช่น ข้าวผัด)
  amount: amount,  // ราคา (เช่น 50)
  date: dateStr,
  time: timeStr,
  originalText: text
};

